const $=s=>document.querySelector(s),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let token=sessionStorage.getItem('village-student-token')||'',data=null,busy=false,view=location.hash==='#travel'?'travel':'study',received=0,demo=false,visiting=null;
async function request(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:{'content-type':'application/json',authorization:'Bearer '+token},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store',signal:AbortSignal.timeout(20000)});const d=await r.json();if(!r.ok)throw Object.assign(Error(d.error||'연결을 확인해 주세요.'),{status:r.status});return d}
function message(t,error=false){$('#status').textContent=t;$('#status').classList.toggle('error',error)}
function display(d){if(data&&d.current&&data.current?.id===d.current.id&&d.current.version<data.current.version)return;if(d!==data)received=Date.now();data=d;$('#entry').hidden=true;$('#studyPage').hidden=view!=='study';$('#travelPage').hidden=view!=='travel';$('#identity').textContent=(d.rooms.find(r=>r.id===d.home)?.label||'우리 반')+' · '+d.name+(demo?' · 연습':'');$('#pointBadge').textContent='✦ '+d.points+' P';$('#presenceCount').textContent=d.peers.length?d.peers.length+'명이 각자의 공부를 함께하고 있어요':'첫 번째 불빛을 켜 주세요';const current=d.current;$('#studyStart').hidden=!!current;$('#activeStudy').hidden=!current;if(current){$('#activeGoal').textContent=current.goal;$('#activeSeat').textContent=current.seat+' · '+current.plan+'분 집중';$('#pauseStudy').textContent=current.status==='active'?'잠깐 쉬기':'다시 집중';$('#pauseStudy').disabled=!d.library||d.paused;$('#reportedMinutes').max=Math.floor(current.elapsed/60)}else $('#finishForm').hidden=true;$('#studyStart button').disabled=!d.library||d.paused;$('#studyPeers').innerHTML=d.peers.length?d.peers.map(p=>`<div class="study-person ${p.status==='집중 중'?'active':''}"><span class="avatar">${p.status==='집중 중'?'📖':'☕'}</span><b>${escape(p.name)}</b><small>${escape(d.rooms.find(r=>r.id===p.room)?.label||'우리 반')}</small><small>${escape(p.seat)} · ${escape(p.status)}</small></div>`).join(''):'<div class="empty">아직 조용한 공부방이에요.<br>내 자리부터 따뜻하게 켜 볼까요?</div>';$('#studyHistory').innerHTML=d.history.length?d.history.map(s=>`<div class="history-row"><span>${new Date(s.created).toLocaleDateString('ko-KR',{month:'short',day:'numeric'})}<p>${s.status==='cancelled'?'보상 없이 종료':Math.floor(s.reported/60)+'분 기록'}</p></span><div><b>${escape(s.goal)}</b><p>${escape(s.reflection)}</p></div><span>+${s.points} P</span></div>`).join(''):'<div class="empty">오늘의 작은 시작이 첫 기록이 됩니다.</div>';$('#passportInfo').innerHTML=`<dl><dt>여행자</dt><dd>${escape(d.name)}</dd><dt>소속</dt><dd>${escape(d.rooms.find(r=>r.id===d.home)?.label||'우리 반')}</dd><dt>발급</dt><dd>${d.passport?new Date(d.passport).toLocaleDateString('ko-KR'):'아직 여권이 없어요'}</dd></dl>`;$('#passportForm').hidden=!!d.passport;$('#passportStamps').innerHTML=d.stamps.map(s=>`<span class="stamp">${escape(d.rooms.find(r=>r.id===s.destination)?.label||'이웃 마을')}<br>방문 완료</span>`).join('');$('#travelGate').textContent=d.travel&&!d.paused?'여행 시간 · 열림':'여행 시간 · 닫힘';$('#campusMap').innerHTML=d.rooms.map((r,i)=>`<button class="village-stop" data-visit="${r.id}" ${!d.travel||d.paused||!d.passport?'disabled':''}><span>${['🏡','🌳','🐄','🌊'][i]}</span><b>${escape(r.label)}</b><small>${r.students}명의 이웃${r.id===d.home?' · 우리 반':''}</small></button>`).join('');if(!d.travel||d.paused){visiting=null;$('#visitView').hidden=true}timer();}
function timer(){if(!data?.current)return;const s=data.current,extra=s.status==='active'&&Date.now()-received<45000?Math.max(0,Math.floor((Date.now()-received)/1000)):0,total=Math.min(s.plan*60,s.elapsed+extra);$('#timer').textContent=String(Math.floor(total/60)).padStart(2,'0')+':'+String(total%60).padStart(2,'0');$('#timerHint').textContent=Date.now()-received>=45000?'연결 확인이 필요해요. 미확인 시간은 적립되지 않아요.':total>=s.plan*60?'집중 시간이 끝났어요. 오늘 한 일을 기록해 주세요.':s.status==='paused'?'쉬는 중 · 휴식 시간은 집중 시간에 포함하지 않아요.':'함께 집중 중 · 다른 앱이나 책으로 공부해도 괜찮아요.'}
async function act(path,body){if(busy){message('앞선 기록을 확인 중이에요. 잠시 뒤 다시 눌러 주세요.');return null}busy=true;document.querySelectorAll('button[type="submit"],#pauseStudy,#finishStudy,#cancelStudy').forEach(b=>b.disabled=true);try{const d=await request(path,body);display(d);message('내 기록이 저장됐어요.');return d}catch(e){message(e.message,true);return null}finally{busy=false;document.querySelectorAll('button[type="submit"],#pauseStudy,#finishStudy,#cancelStudy').forEach(b=>b.disabled=false);if(data)display(data)}}
async function refresh(){if(busy||demo||!token)return;busy=true;try{const d=data?.current?await request('/api/campus/study',{action:'heartbeat',id:data.current.id}):await request('/api/campus');display(d);message(d.library&&!d.paused?'목표와 마무리 기록은 본인과 교사에게만 보여요.':'선생님이 공부학교를 쉬는 시간으로 설정했어요.')}catch(e){if(e.status===401){$('#entry').hidden=false;$('#studyPage').hidden=true;$('#travelPage').hidden=true;token=''}message('연결 확인 필요 · '+e.message,true)}finally{busy=false}}
$('.campus-tabs').onclick=e=>{const b=e.target.closest('[data-page]');if(!b)return;view=b.dataset.page;location.hash=view;document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('selected',x===b));if(data)display(data)};
$('#studyStart').onsubmit=async e=>{e.preventDefault();if(demo){message('연습은 화면 둘러보기예요. 시간 저장과 포인트는 학급 입장 후 사용할 수 있어요.');return}const id=sessionStorage.getItem('study-start-id')||crypto.randomUUID();sessionStorage.setItem('study-start-id',id);const d=await act('/api/campus/study',{action:'start',id,goal:$('#studyGoal').value,plan:Number($('#studyPlan').value),seat:$('#studySeat').value});if(d)sessionStorage.removeItem('study-start-id')};
$('#pauseStudy').onclick=()=>act('/api/campus/study',{action:data.current.status==='active'?'pause':'resume',id:data.current.id});$('#cancelStudy').onclick=async()=>{if(!data.current)return;await act('/api/campus/study',{action:'cancel',id:data.current.id})};$('#finishStudy').onclick=async()=>{const d=await act('/api/campus/study',{action:'pause',id:data.current.id});if(!d?.current)return;$('#finishForm').hidden=false;$('#reportedMinutes').value=Math.floor(d.current.elapsed/60);$('#reportedMinutes').focus()};$('#backToTimer').onclick=()=>$('#finishForm').hidden=true;$('#finishForm').onsubmit=async e=>{e.preventDefault();await act('/api/campus/study',{action:'finish',id:data.current.id,minutes:Number($('#reportedMinutes').value),reflection:$('#studyReflection').value})};$('#passportForm').onsubmit=e=>{e.preventDefault();if(demo){message('여권 발급은 학급 입장 후 사용할 수 있어요.');return}act('/api/campus/passport',{answer:Number(new FormData(e.target).get('promise'))})};
$('#campusMap').onclick=async e=>{const b=e.target.closest('[data-visit]');if(!b||busy)return;busy=true;try{const d=await request('/api/campus/visit',{destination:b.dataset.visit});visiting=d.destination;$('#visitTitle').textContent=d.label+'에 오신 것을 환영해요';$('#visitResidents').innerHTML=d.residents.map(p=>`<article class="resident"><span class="house">${['🏡','🐄','🌳','🌊'][p.job]}</span><b>${escape(p.name)}</b><small>${['채소 농업인','낙농업인','과수 농업인','양식업인'][p.job]} · 밭 ${p.plots}칸</small><div class="mini-plots">${Array.from({length:Math.min(6,p.plots)},(_,i)=>i<p.planted?'🌱':'🟫').join('')}</div><small>심은 밭 ${p.planted}칸</small></article>`).join('');$('#visitView').hidden=false;display(await request('/api/campus'));$('#visitView').scrollIntoView({behavior:'smooth'});message('방문 도장을 받았어요. 내 농장과 재고는 그대로예요.')}catch(e){message(e.message,true)}finally{busy=false}};$('#returnHome').onclick=()=>{visiting=null;$('#visitView').hidden=true;$('#campusMap').scrollIntoView({behavior:'smooth'});message('우리 반으로 돌아왔어요.')};$('#demoEntry').onclick=()=>{demo=true;display({rooms:[{id:'demo',label:'연습 마을',students:1}],home:'demo',name:'새싹 여행자',travel:false,library:true,paused:false,passport:0,stamps:[],current:null,history:[],points:0,peers:[]});message('혼자 둘러보기 · 실제 친구와 공부 기록은 학급 입장 후 연결돼요.')};
setInterval(timer,1000);setInterval(refresh,15000);window.addEventListener('online',refresh);if(token)refresh();else{$('#entry').hidden=false;message('학생 계정으로 입장하면 포인트와 기록이 저장돼요.')}document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('selected',x.dataset.page===view));
